"""Collect scoped typed operation records from the kernel receipts of this run; every listed proof must have a receipt."""
from pathlib import Path
import json
B=Path(__file__).resolve().parents[1]
def load(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def save(p,v):Path(p).write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
R='InnerProductFable.SectorForm.';H='InnerProductFable.HermitianSectorForm.'
RECORDS=[
 ('IP-01','Pairing, disjoint supports and sector additivity on the rational sector carrier','Gram matrix G on Fin n -> Q; carrier vectors u, v, x, y','pair G x y = x . (G y) with pair G x x = qf G x (the Born carrier readout); DisjointSupport; SectorAdditive; the l1 sector weight is additive on disjoint supports; qf (u+v) expands into the two pairings; pair on unit vectors reads the entry',[R+n for n in ['pair','pair_self','DisjointSupport','SectorAdditive','l1_disjoint_additive','qf_add_vec',"mulVec_single_one'",'pair_single_single','qf_single','disjoint_single_single','single_ne_zero']]),
 ('IP-02','Sector additivity forces an orthogonal sector basis','Sector-additive G (symmetric for the entrywise statement)','G i j + G j i = 0 for i != j; a symmetric sector-additive G is diagonal; the readout of any sector-additive G is sum G i i * x i ^ 2 (the skew part is invisible)',[R+n for n in ['offdiag_pair_sum_eq_zero','transpose_entry','offdiag_eq_zero','eq_diagonal_of_sectorAdditive','qf_diagonal','qf_transpose','symmPart','symmPart_transpose','symmPart_apply','qf_symmPart','sectorAdditive_symmPart','qf_eq_sum_diag_sq_of_sectorAdditive']]),
 ('IP-03','Sector permutations, invariance and the generated group','Sector permutations sigma, tau; a set S of permutations','permute sigma moves unit vectors forward; Invariant and TransitiveOn; Generated S is the group generated by S; invariance is closed under 1, products and inverses, so generators suffice',[R+n for n in ['permute','permute_single','Invariant','TransitiveOn','Generated','permute_one','permute_mul','permute_inv_left','permute_inv_right','invariant_one','invariant_mul','invariant_inv','invariant_of_generated']]),
 ('IP-04','Transitive symmetry collapses the diagonal: the form is a scalar multiple of the identity','Symmetric sector-additive G invariant under S with S (or Generated S) transitive; a sector i0','G i i is constant; G = G i0 i0 * 1; qf G x = c * (x . x); pair G x y = c * (x . y); c > 0 for a positive-definite readout',[R+n for n in ['diag_eq_of_invariant','diag_const_of_transitive','eq_smul_one','eq_smul_one_generated','qf_eq_scale_dot','pair_smul_one','pair_eq_scale_dot','scale_pos']]),
 ('IP-05','Uniqueness and nonvacuity of the selected form','Two selected forms G, G2; the standard form 1','Equal once one diagonal entry is matched; proportional in general; every diagonal form is sector additive; 1 is sector additive, invariant under every permutation and positive definite; the unit-normalised selected form is 1',[R+n for n in ['unique_of_normalized','unique_up_to_scale','pair_diagonal_eq_zero_of_disjoint','diagonal_sectorAdditive','one_sectorAdditive','dot_permute','one_invariant','one_posdef','eq_one_of_normalized']]),
 ('IP-06','Countermodels: each hypothesis is used','diag(1,2) and 1 + (all ones) on two sectors; the swap','diag(1,2) is symmetric, positive definite and sector additive but not swap invariant and not scalar; 1 + (all ones) is symmetric, positive definite and invariant under the swap (which is transitive) but not sector additive and not scalar',[R+n for n in ['diag12','diag12_transpose','diag12_sectorAdditive','diag12_qf','diag12_posdef','diag12_not_invariant_swap','diag12_not_scalar','unif12','unif12_apply','unif12_transpose','unif12_qf','unif12_posdef','permute_swap_zero','permute_swap_one','S₂','S₂_transitive','unif12_invariant','unif12_not_sectorAdditive','unif12_not_scalar']]),
 ('IP-07','Hermitian sector additivity along the directions 1 and i','Gaussian-rational H; sectors i != j','hf H (e_i s + e_j t) expands with the two cross terms; the real direction kills re(H i j + H j i), the imaginary direction kills im(H j i - H i j); a Hermitian sector-additive H has zero off-diagonal entries',[H+n for n in ['DisjointSupport','SectorAdditive','disjoint_single_single','cross_single','hf_single_add_single','offdiag_re_add_re','offdiag_im_sub_im','offdiag_eq_zero']]),
 ('IP-08','Hermitian permutations, generated group, diagonal collapse and the scalar form','Hermitian sector-additive H invariant under S with Generated S transitive; a sector i0','Real diagonal constant on orbits; H = re(H i0 i0) * 1 (rational scalar); hf H x = re(H i0 i0) * vnorm x; the scale is positive for a positive-definite readout',[H+n for n in ['permute','permute_single','Invariant','TransitiveOn','hf_single_one','diag_re_eq_of_invariant','diag_re_const_of_transitive','Generated','permute_one','permute_mul','permute_inv_left','permute_inv_right','invariant_one','invariant_mul','invariant_inv','invariant_of_generated','diag_eq_of_hermitian_transitive','eq_smul_one','eq_smul_one_generated','hf_eq_scale_vnorm','single_ne_zero','scale_pos']]),
 ('IP-09','Hermitian uniqueness, nonvacuity and the two-direction control','Two selected Hermitian forms; the identity; the matrix [[1, i], [-i, 1]]','Equal once normalised; 1 is sector additive, invariant and positive definite; [[1,i],[-i,1]] is Hermitian and additive on (e0, e1) along the real direction yet not sector additive, so the imaginary direction is needed',[H+n for n in ['unique_of_normalized','eq_one_of_normalized','normSq_add_of_disjoint','vnorm_add_of_disjoint','one_sectorAdditive','vnorm_permute','one_invariant','one_posdef','imagLeak12','imagLeak12_apply_00','imagLeak12_apply_01','imagLeak12_apply_10','imagLeak12_apply_11','imagLeak12_hermitian','imagLeak12_real_direction_additive','imagLeak12_imag_direction_not_additive','imagLeak12_not_sectorAdditive']]),
]
def collect():
    by={e['name']:e for e in load(B/'verification/kernel_axioms.json')['printed_receipts']};records=[]
    for id_,name,inputs,result,proofs in sorted(RECORDS,key=lambda r:r[0]):
        missing=[p for p in proofs if p not in by]
        if missing:raise RuntimeError('No receipt for '+', '.join(missing))
        records.append({'id':id_,'name':name,'inputs':inputs,'output_or_relation':result,'status':'KERNEL_CHECKED_TYPED_OPERATION','admissible_substitution':'Substitute only matching carrier types and supply every displayed binder; sector additivity and the symmetry set are hypotheses, not consequences; the scale is a unit choice.','proofs':[by[p] for p in proofs]})
    save(B/'operad_delta.json',{'schema_version':2,'namespace':'IP-SECTOR-FORM','records':records,'formal_operad_claim':'Scoped typed operations with kernel-checked relations and exact receipts; no complete higher-arity operad is claimed.','authority_effect':'None'})
    listed={p for r in RECORDS for p in r[4]};unlisted=sorted(set(by)-listed)
    print(json.dumps({'records':len(records),'proofs':sum(len(r['proofs']) for r in records),'receipts_not_in_records':unlisted}))
if __name__=='__main__':collect()
